def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    n = h * w

    # Sparse colors are the symbols placed at intersections of the grid lines;
    # frequent colors form the repeating lattice/background.
    marker_colors = {
        color for color, count in counts.items()
        if color != background and count <= max(2, n // 10)
    }
    if not marker_colors:
        return [[background]]

    marker_rows = [r for r in range(h) if any(v in marker_colors for v in grid[r])]
    marker_cols = [c for c in range(w) if any(grid[r][c] in marker_colors for r in range(h))]
    if len(marker_rows) < 2 or len(marker_cols) < 2:
        return [[background]]

    out = []
    for r0, r1 in zip(marker_rows, marker_rows[1:]):
        row = []
        for c0, c1 in zip(marker_cols, marker_cols[1:]):
            corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            color = corners[0]
            if color in marker_colors and all(v == color for v in corners):
                row.append(color)
            else:
                row.append(background)
        out.append(row)
    return out


